const { ShopifyClientError } = require('../errors');

const COLLECTIONS_QUERY = `
  query($cursor: String) {
    collections(first: 250, after: $cursor) {
      edges {
        node {
          id
          handle
          title
          descriptionHtml
          templateSuffix
          sortOrder
          image {
            url
            altText
          }
          seo {
            title
            description
          }
          ruleSet {
            appliedDisjunctively
            rules {
              column
              relation
              condition
            }
          }
        }
      }
      pageInfo {
        hasNextPage
        endCursor
      }
    }
  }
`;

const COLLECTION_CREATE_MUTATION = `
  mutation collectionCreate($input: CollectionInput!) {
    collectionCreate(input: $input) {
      collection {
        id
        handle
        title
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const COLLECTION_UPDATE_MUTATION = `
  mutation collectionUpdate($input: CollectionInput!) {
    collectionUpdate(input: $input) {
      collection {
        id
        handle
        title
        updatedAt
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const COLLECTION_DELETE_MUTATION = `
  mutation collectionDelete($input: CollectionDeleteInput!) {
    collectionDelete(input: $input) {
      deletedCollectionId
      userErrors {
        field
        message
      }
    }
  }
`;

function throwOnUserErrors(operation, userErrors) {
  if (!userErrors || userErrors.length === 0) {
    return;
  }

  throw new ShopifyClientError(`${operation} failed`, {
    code: 'SHOPIFY_USER_ERROR',
    details: {
      userErrors
    }
  });
}

function createCollectionInput(collectionData) {
  return {
    title: collectionData.title,
    handle: collectionData.handle,
    descriptionHtml: collectionData.descriptionHtml,
    templateSuffix: collectionData.templateSuffix,
    sortOrder: collectionData.sortOrder,
    image: collectionData.image
      ? { src: collectionData.image.url, altText: collectionData.image.altText }
      : undefined,
    seo: collectionData.seo
      ? {
          title: collectionData.seo.title,
          description: collectionData.seo.description
        }
      : undefined,
    ruleSet: collectionData.ruleSet
      ? {
          appliedDisjunctively: collectionData.ruleSet.appliedDisjunctively,
          rules: collectionData.ruleSet.rules.map((rule) => ({
            column: rule.column,
            relation: rule.relation,
            condition: rule.condition
          }))
        }
      : undefined
  };
}

function createCollectionsClient({ graphql }) {
  return {
    async listAll() {
      const collections = [];
      let hasNextPage = true;
      let cursor = null;

      while (hasNextPage) {
        const data = await graphql(COLLECTIONS_QUERY, { cursor });
        collections.push(...data.collections.edges.map((edge) => edge.node));
        hasNextPage = data.collections.pageInfo.hasNextPage;
        cursor = data.collections.pageInfo.endCursor;
      }

      return collections;
    },

    async create(collectionData) {
      const data = await graphql(COLLECTION_CREATE_MUTATION, {
        input: createCollectionInput(collectionData)
      });

      throwOnUserErrors('Collection create', data.collectionCreate.userErrors);
      return data.collectionCreate.collection;
    },

    async update(collectionId, changes) {
      const data = await graphql(COLLECTION_UPDATE_MUTATION, {
        input: {
          id: collectionId,
          ...changes
        }
      });

      throwOnUserErrors('Collection update', data.collectionUpdate.userErrors);
      return data.collectionUpdate.collection;
    },

    async delete(collectionId) {
      const data = await graphql(COLLECTION_DELETE_MUTATION, {
        input: { id: collectionId }
      });

      throwOnUserErrors('Collection delete', data.collectionDelete.userErrors);
      return data.collectionDelete.deletedCollectionId;
    },

    createInput: createCollectionInput
  };
}

module.exports = {
  createCollectionsClient,
  createCollectionInput,
  COLLECTIONS_QUERY,
  COLLECTION_CREATE_MUTATION,
  COLLECTION_UPDATE_MUTATION,
  COLLECTION_DELETE_MUTATION
};
